import { DualSlider } from '@/lib/designsystem';
import { useState } from 'react';

function MyComponent() {
  const [price, setPrice] = useState<[number, number]>([10, 50]);

  return (
    <DualSlider
      label="Price Range"
      value={price}
      min={0}
      max={100}
      onChange={setPrice}
    />
  );
}
